CREATE VIEW v_conversation_trace (`session_id` String, `session_date` Date, `event_uid` String, `compacted_parent_uid` String, `source_file` String, `source_generation` UInt32, `source_line_no` UInt64, `source_offset` UInt64, `source_ref` String, `event_time` DateTime64(3), `event_order` UInt64, `turn_seq` UInt32, `turn_id` String, `actor_role` LowCardinality(String), `event_class` LowCardinality(String), `payload_type` LowCardinality(String), `call_id` String, `name` LowCardinality(String), `phase` String, `item_id` String, `text_content` String, `payload_json` String, `token_usage_json` String, `endpoint_kind` LowCardinality(String), `token_usage_buckets` Map(String, UInt64), `token_usage_native_units` Map(String, Float64)) AS SELECT session_id, session_date, event_uid, compacted_parent_uid, source_file, source_generation, source_line_no, source_offset, source_ref, ifNull(parseDateTime64BestEffortOrNull(record_ts), ingested_at) AS event_time, row_number() OVER (PARTITION BY session_id ORDER BY ifNull(parseDateTime64BestEffortOrNull(record_ts), ingested_at) ASC, source_file ASC, source_generation ASC, source_offset ASC, source_line_no ASC, toUInt32(JSONExtractUInt(payload_json, 'moraine_emission_index')) ASC, event_uid ASC) AS event_order, if(toUInt32OrZero(turn_id) > 0, toUInt32OrZero(turn_id), greatest(toUInt32(1), toUInt32(sum(if((actor_role = 'user') AND (event_class = 'message'), 1, 0)) OVER (PARTITION BY session_id ORDER BY ifNull(parseDateTime64BestEffortOrNull(record_ts), ingested_at) ASC, source_file ASC, source_generation ASC, source_offset ASC, source_line_no ASC, toUInt32(JSONExtractUInt(payload_json, 'moraine_emission_index')) ASC, event_uid ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)))) AS turn_seq, turn_id, actor_role, event_class, payload_type, call_id, name, phase, item_id, text_content, payload_json, token_usage_json, endpoint_kind, token_usage_buckets, token_usage_native_units FROM v_all_events
